import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';

// Import all the components from your components folder
import Login from './components/Login';
import Signup from './components/Signup';
import CandidateDashboard from './components/CandidateDashboard';
import ExpertDashboard from './components/ExpertDashboard';
import AdminDashboard from './components/AdminDashboard';
import Interview from './components/Interview';
import Result from './components/Result';

/**
 * Protected Route Helper
 * Checks the 'role' stored in localStorage to ensure users can only
 * access pages they are authorized for.
 */
const ProtectedRoute = ({ children, allowedRoles }) => {
  const userRole = localStorage.getItem('role');
  
  // If no user is logged in, redirect to the landing/login page
  if (!userRole) {
    return <Navigate replace to="/" />;
  }
  
  // If the user's role is not in the allowed list for this page, redirect to login
  if (allowedRoles && !allowedRoles.includes(userRole)) {
    return <Navigate replace to="/" />;
  }
  
  return children;
};

function App() {
  return (
    <Router>
      <Routes>
        
        {/* === PUBLIC ROUTES === */}
        {/* This ensures that when you visit localhost:3000, you see the Login page */}
        <Route path="/" element={<Login />} />
        <Route path="/signup" element={<Signup />} />

        {/* === ROLE-BASED DASHBOARDS === */}
        {/* Protected so only users with the correct role can enter */}
        <Route 
          path="/candidate" 
          element={
            <ProtectedRoute allowedRoles={['Candidate']}>
              <CandidateDashboard />
            </ProtectedRoute>
          } 
        />
        
        <Route 
          path="/expert" 
          element={
            <ProtectedRoute allowedRoles={['Expert']}>
              <ExpertDashboard />
            </ProtectedRoute>
          } 
        />
        
        <Route 
          path="/admin" 
          element={
            <ProtectedRoute allowedRoles={['Admin']}>
              <AdminDashboard />
            </ProtectedRoute>
          } 
        />

        {/* === SHARED WORKFLOW ROUTES === */}
        
        {/* Both Candidates and Experts need access to the Live Interview room */}
        <Route 
          path="/interview" 
          element={
            <ProtectedRoute allowedRoles={['Candidate', 'Expert']}>
              <Interview />
            </ProtectedRoute>
          } 
        />

        {/* Result page for Candidates to view their AI + Expert evaluation */}
        <Route 
          path="/result" 
          element={
            <ProtectedRoute allowedRoles={['Candidate']}>
              <Result />
            </ProtectedRoute>
          } 
        />

        {/* === FALLBACK === */}
        {/* If a user enters a wrong URL, redirect them back to the start */}
        <Route path="*" element={<Navigate to="/" />} />
        
      </Routes>
    </Router>
  );
}

export default App;
